import { test, expect } from '@playwright/test';

test.describe('Product Search Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example-ecommerce.com');
    await page.waitForLoadState('networkidle');
  });

  test('should display search input field on page load', async ({ page }) => {
    const searchInput = page.getByRole('searchbox', { name: /search/i });
    await expect(searchInput).toBeVisible();
    await expect(searchInput).toHaveAttribute('placeholder', /search/i);
  });

  test('should show instant search results when typing keyword', async ({ page }) => {
    const searchInput = page.getByRole('searchbox', { name: /search/i });

    await searchInput.click();
    await searchInput.type('laptop', { delay: 100 });

    // Wait for results to appear
    const resultsContainer = page.getByRole('region', { name: /search results/i });
    await expect(resultsContainer).toBeVisible();

    // Verify product results are displayed
    const productItems = page.getByRole('listitem').filter({ has: page.getByRole('link', { name: /laptop/i }) });
    const count = await productItems.count();
    expect(count).toBeGreaterThan(0);
  });

  test('should filter results as user types different keywords', async ({ page }) => {
    const searchInput = page.getByRole('searchbox', { name: /search/i });

    // First search
    await searchInput.click();
    await searchInput.type('phone', { delay: 50 });

    let resultsContainer = page.getByRole('region', { name: /search results/i });
    await expect(resultsContainer).toBeVisible();

    let firstResults = page.getByRole('listitem');
    const firstCount = await firstResults.count();
    expect(firstCount).toBeGreaterThan(0);

    // Clear and search for different keyword
    await searchInput.clear();
    await searchInput.type('tablet', { delay: 50 });

    resultsContainer = page.getByRole('region', { name: /search results/i });
    await expect(resultsContainer).toBeVisible();

    // Verify results have changed
    const secondResults = page.getByRole('listitem');
    const secondCount = await secondResults.count();
    expect(secondCount).toBeGreaterThan(0);
  });

  test('should display product details in search results', async ({ page }) => {
    const searchInput = page.getByRole('searchbox', { name: /search/i });

    await searchInput.click();
    await searchInput.type('camera', { delay: 100 });

    const resultsContainer = page.getByRole('region', { name: /search results/i });
    await expect(resultsContainer).toBeVisible();

    // Verify product name is visible
    const productName = page.getByRole('heading', { level: 3 }).first();
    await expect(productName).toBeVisible();

    // Verify price is displayed
    const priceText = page.getByText(/\$\d+(\.\d{2})?/);
    await expect(priceText).toBeVisible();
  });

  test('should handle empty search results gracefully', async ({ page }) => {
    const searchInput = page.getByRole('searchbox', { name: /search/i });

    await searchInput.click();
    await searchInput.type('xyznonexistentproduct123', { delay: 50 });

    // Wait for results area to update
    await page.waitForTimeout(500);

    // Check for no results message
    const noResultsMessage = page.getByText(/no products found|no results/i);
    const resultsContainer = page.getByRole('region', { name: /search results/i });

    // Either no results message or empty results container should be visible
    const messageVisible = await noResultsMessage.isVisible().catch(() => false);
    const containerVisible = await resultsContainer.isVisible().catch(() => false);

    expect(messageVisible || containerVisible).toBeTruthy();
  });

  test('should allow user to click on search result to view product details', async ({ page }) => {
    const searchInput = page.getByRole('searchbox', { name: /search/i });

    await searchInput.click();
    await searchInput.type('headphones', { delay: 100 });

    const resultsContainer = page.getByRole('region', { name: /search results/i });
    await expect(resultsContainer).toBeVisible();

    // Click on first product result
    const firstProductLink = page.getByRole('link').filter({ has: page.getByText(/headphones/i) }).first();
    await expect(firstProductLink).toBeVisible();

    await firstProductLink.click();

    // Verify navigation to product details page
    await page.waitForLoadState('networkidle');
    const productTitle = page.getByRole('heading', { level: 1 });
    await expect(productTitle).toBeVisible();
  });
});
